const LogoLoader = ({ size = "md" }) => {
  const sizeConfig = {
    sm: {
      container: "w-40 h-20",
      logo: "w-12 h-12",
      text: "text-sm",
      spacing: "space-y-4",
    },
    md: {
      container: "w-64 h-32",
      logo: "w-20 h-20",
      text: "text-base",
      spacing: "space-y-8",
    },
  };

  const current = sizeConfig[size] || sizeConfig.md;

  return (
    <div
      className={`flex flex-col items-center justify-center min-h-[50vh] ${current.spacing}`}
    >
      <div
        className={`relative flex items-center justify-center ${current.container}`}
      >
        <Logo
          className={`absolute object-contain swap-left ${current.logo}`}
          style={{ left: "15%" }}
          fillColor="#BC3FDE"
        />

        <Logo
          className={`absolute object-contain swap-right ${current.logo}`}
          style={{ right: "15%" }}
          fillColor="#FF03DE"
        />
      </div>

      <p
        className={`font-medium tracking-widest text-slate-500 animate-pulse ${current.text}`}
      >
        Loading...
      </p>

      <style>{`
        .swap-left {
          animation: orbitLeft 1.8s infinite ease-in-out;
        }
        .swap-right {
          animation: orbitRight 1.8s infinite ease-in-out;
        }

        /* Moves the Colored logo to the right, crossing IN FRONT */
        @keyframes orbitLeft {
          0%   { transform: translateX(0) scale(1); z-index: 10; }
          25%  { transform: translateX(70%) scale(1.15); z-index: 10; }
          50%  { transform: translateX(140%) scale(1); z-index: 1; }
          75%  { transform: translateX(70%) scale(0.85); z-index: 1; }
          100% { transform: translateX(0) scale(1); z-index: 10; }
        }

        /* Moves the Grayscale logo to the left, crossing BEHIND */
        @keyframes orbitRight {
          0%   { transform: translateX(0) scale(1); z-index: 1; }
          25%  { transform: translateX(-70%) scale(0.85); z-index: 1; }
          50%  { transform: translateX(-140%) scale(1); z-index: 10; }
          75%  { transform: translateX(-70%) scale(1.15); z-index: 10; }
          100% { transform: translateX(0) scale(1); z-index: 1; }
        }
      `}</style>
    </div>
  );
};

